{
  "name": "opencode-agent-supervisor",
  "version": "2.10.0",
  "description": "Agent supervision middleware for OpenCode: a reasoning-audit loop, session memo, tool guard, and consoles for agent self-serve tools and engineer directives.",
  "license": "MIT",
  "author": "Jay Flowers",
  "type": "module",
  "main": "./index.ts",
  "exports": {
    ".": "./index.ts",
    "./server": "./index.ts"
  },
  "files": [
    "index.ts",
    "src/",
    "skills/",
    "README.md",
    "CHANGELOG.md",
    "LICENSE"
  ],
  "engines": {
    "opencode": ">=1.19.0"
  },
  "scripts": {
    "test": "bun test",
    "test:node": "node --test test/audit.test.ts test/memo.test.ts test/reminders.test.ts test/directives.test.ts test/console.test.ts test/gates.test.ts test/plugin-log.test.ts test/config-file.test.ts test/arg-repair.test.ts test/guard-profiles.test.ts test/external-access.test.ts",
    "typecheck": "tsc --noEmit -p .",
    "verify:package": "node scripts/verify-package.mjs",
    "prepublishOnly": "npm run typecheck && npm run verify:package"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "supervisor",
    "process-supervision",
    "agent-tools",
    "chain-of-thought",
    "ai-safety"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/jflowers/opencode-supervisor.git"
  },
  "bugs": {
    "url": "https://github.com/jflowers/opencode-supervisor/issues"
  },
  "homepage": "https://github.com/jflowers/opencode-supervisor#readme",
  "publishConfig": {
    "access": "public"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.19.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.19.4",
    "bun-types": "^1.4.4",
    "typescript": "^7.0.2"
  }
}
